{
  "name": "AmortizaEase",
  "description": "A high-end financial management dashboard for tracking installment purchases and monthly amortizations with glassmorphism aesthetics."
}

export interface Amortization {
  id: string;
  amount: number;
  date: string;
}

export interface Purchase {
  id: string;
  name: string;
  totalValue: number;
  installments: number;
  startDate: string;
  amortizations: Amortization[];
}

export type ToastType = 'success' | 'error' | 'info';

export interface ToastMessage {
  id: string;
  message: string;
  type: ToastType;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { Purchase, Amortization, ToastMessage } from './types';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import PurchaseModal from './components/PurchaseModal';
import AmortizationModal from './components/AmortizationModal';
import ConfirmationModal from './components/ConfirmationModal';
import Toast from './components/Toast';

const App: React.FC = () => {
  const [purchases, setPurchases] = useState<Purchase[]>([]);
  const [isPurchaseModalOpen, setPurchaseModalOpen] = useState(false);
  const [isAmortizationModalOpen, setAmortizationModalOpen] = useState(false);
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
  const [selectedPurchase, setSelectedPurchase] = useState<Purchase | null>(null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Initialize from LocalStorage
  useEffect(() => {
    const saved = localStorage.getItem('amortiza_ease_data');
    if (saved) {
      try {
        setPurchases(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load data", e);
      }
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    localStorage.setItem('amortiza_ease_data', JSON.stringify(purchases));
  }, [purchases]);

  const addToast = useCallback((message: string, type: ToastMessage['type'] = 'success') => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 3000);
  }, []);

  const handleAddPurchase = (purchaseData: Omit<Purchase, 'id' | 'amortizations'>) => {
    const newPurchase: Purchase = {
      ...purchaseData,
      id: crypto.randomUUID(),
      amortizations: [],
    };
    setPurchases((prev) => [...prev, newPurchase]);
    setPurchaseModalOpen(false);
    addToast("Compra cadastrada com sucesso!");
  };

  const handleDeletePurchase = () => {
    if (selectedPurchase) {
      setPurchases((prev) => prev.filter((p) => p.id !== selectedPurchase.id));
      setDeleteModalOpen(false);
      setSelectedPurchase(null);
      addToast("Compra removida com sucesso.", 'info');
    }
  };

  const handleAddAmortization = (amount: number, date: string) => {
    if (selectedPurchase) {
      const newAmortization: Amortization = {
        id: crypto.randomUUID(),
        amount,
        date,
      };
      setPurchases((prev) =>
        prev.map((p) =>
          p.id === selectedPurchase.id
            ? { ...p, amortizations: [...p.amortizations, newAmortization] }
            : p
        )
      );
      setAmortizationModalOpen(false);
      addToast("Amortização adicionada!");
    }
  };

  const openAmortizationModal = (purchase: Purchase) => {
    setSelectedPurchase(purchase);
    setAmortizationModalOpen(true);
  };

  const openDeleteModal = (purchase: Purchase) => {
    setSelectedPurchase(purchase);
    setDeleteModalOpen(true);
  };

  return (
    <div className="flex flex-col min-h-screen pb-10">
      <Header onAddClick={() => setPurchaseModalOpen(true)} />

      <main className="container mx-auto px-4 mt-8 flex-grow">
        {purchases.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
            <i className="fa-solid fa-receipt text-6xl mb-4 opacity-20"></i>
            <p className="text-xl">Nenhuma compra cadastrada.</p>
            <button 
              onClick={() => setPurchaseModalOpen(true)}
              className="mt-4 bg-indigo-600 text-white px-6 py-2 rounded-full hover:bg-indigo-700 shadow-lg"
            >
              Cadastrar primeira compra
            </button>
          </div>
        ) : (
          <Dashboard 
            purchases={purchases} 
            onAddAmortization={openAmortizationModal} 
            onDelete={openDeleteModal}
          />
        )}
      </main>

      {isPurchaseModalOpen && (
        <PurchaseModal 
          onClose={() => setPurchaseModalOpen(false)} 
          onSubmit={handleAddPurchase} 
        />
      )}

      {isAmortizationModalOpen && selectedPurchase && (
        <AmortizationModal 
          purchase={selectedPurchase}
          onClose={() => setAmortizationModalOpen(false)} 
          onSubmit={handleAddAmortization} 
        />
      )}

      {isDeleteModalOpen && selectedPurchase && (
        <ConfirmationModal 
          title="Excluir Compra"
          message={`Tem certeza que deseja excluir "${selectedPurchase.name}"? Esta ação não pode ser desfeita.`}
          onConfirm={handleDeletePurchase}
          onCancel={() => setDeleteModalOpen(false)}
        />
      )}

      <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2">
        {toasts.map((toast) => (
          <Toast key={toast.id} toast={toast} />
        ))}
      </div>
    </div>
  );
};

export default App;

