export default Dashboard;

import React, { useState } from 'react';
import { Purchase } from '../types';

interface PurchaseCardProps {
  purchase: Purchase;
  onAddAmortization: () => void;
  onDelete: () => void;
}

const PurchaseCard: React.FC<PurchaseCardProps> = ({ purchase, onAddAmortization, onDelete }) => {
  const [showDetails, setShowDetails] = useState(false);

  const totalAmortized = purchase.amortizations.reduce((acc, curr) => acc + curr.amount, 0);
  const currentBalance = Math.max(0, purchase.totalValue - totalAmortized);
  const monthlyInstallment = purchase.totalValue / purchase.installments;
  const progressPercentage = (totalAmortized / purchase.totalValue) * 100;

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('pt-BR');
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  return (
    <div className="bg-white rounded-[16px] border border-slate-100 p-6 shadow-sm card-hover flex flex-col h-full relative overflow-hidden">
      <div className="absolute top-0 right-0 p-4 flex gap-2">
        <button 
          onClick={onDelete}
          className="text-slate-300 hover:text-red-500 transition-colors p-2"
          title="Excluir"
        >
          <i className="fa-solid fa-trash-can"></i>
        </button>
      </div>

      <div className="mb-4">
        <span className="text-xs font-bold text-indigo-500 uppercase tracking-wider">{formatDate(purchase.startDate)}</span>
        <h3 className="text-xl font-bold text-slate-800 mt-1">{purchase.name}</h3>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-6">
        <div>
          <p className="text-xs text-slate-500 uppercase font-semibold">Total Original</p>
          <p className="text-lg font-bold text-slate-700">{formatCurrency(purchase.totalValue)}</p>
        </div>
        <div>
          <p className="text-xs text-slate-500 uppercase font-semibold">Parcela Est.</p>
          <p className="text-lg font-bold text-indigo-600">{formatCurrency(monthlyInstallment)}</p>
        </div>
      </div>

      <div className="bg-slate-50 rounded-xl p-4 mb-6">
        <div className="flex justify-between items-end mb-2">
          <div>
            <p className="text-xs text-slate-500 uppercase font-semibold">Saldo Devedor Atual</p>
            <p className="text-2xl font-black text-slate-900">{formatCurrency(currentBalance)}</p>
          </div>
          <span className="text-xs font-bold text-slate-400">
            {purchase.installments}x
          </span>
        </div>

        <div className="w-full bg-slate-200 rounded-full h-2 mb-1">
          <div 
            className="bg-indigo-600 h-2 rounded-full transition-all duration-1000" 
            style={{ width: `${Math.min(100, progressPercentage)}%` }}
          ></div>
        </div>
        <div className="flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase">
          <span>{Math.round(progressPercentage)}% pago</span>
          <span>Amortizado: {formatCurrency(totalAmortized)}</span>
        </div>
      </div>

      <div className="flex gap-2 mt-auto">
        <button 
          onClick={onAddAmortization}
          className="flex-1 bg-slate-100 hover:bg-indigo-50 text-indigo-600 font-bold py-2.5 rounded-xl transition-all"
        >
          <i className="fa-solid fa-coins mr-2"></i> Amortizar
        </button>
        <button 
          onClick={() => setShowDetails(!showDetails)}
          className={`px-4 py-2.5 rounded-xl transition-all ${showDetails ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600'}`}
        >
          <i className={`fa-solid ${showDetails ? 'fa-chevron-up' : 'fa-list-ul'}`}></i>
        </button>
      </div>

      {showDetails && (
        <div className="mt-6 border-t border-slate-100 pt-4 animate-in fade-in slide-in-from-top-4 duration-300">
          <h4 className="text-xs font-bold text-slate-500 uppercase mb-3">Histórico de Amortizações</h4>
          {purchase.amortizations.length === 0 ? (
            <p className="text-sm text-slate-400 italic">Nenhuma amortização registrada.</p>
          ) : (
            <ul className="space-y-2">
              {purchase.amortizations.map((item) => (
                <li key={item.id} className="flex justify-between items-center p-2 rounded-lg bg-slate-50/50">
                  <span className="text-xs text-slate-600">{formatDate(item.date)}</span>
                  <span className="text-sm font-bold text-green-600">+{formatCurrency(item.amount)}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
};

export default PurchaseCard;

import React, { useState } from 'react';
import { Purchase } from '../types';

interface PurchaseModalProps {
  onClose: () => void;
  onSubmit: (data: Omit<Purchase, 'id' | 'amortizations'>) => void;
}

const PurchaseModal: React.FC<PurchaseModalProps> = ({ onClose, onSubmit }) => {
  const [name, setName] = useState('');
  const [totalValue, setTotalValue] = useState('');
  const [installments, setInstallments] = useState('1');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [errors, setErrors] = useState<Record<string, boolean>>({});

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: Record<string, boolean> = {};

    if (!name.trim()) newErrors.name = true;
    if (!totalValue || Number(totalValue) <= 0) newErrors.totalValue = true;
    if (!installments || Number(installments) <= 0) newErrors.installments = true;

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    onSubmit({
      name,
      totalValue: Number(totalValue),
      installments: Number(installments),
      startDate,
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-md" onClick={onClose}></div>
      <div className="relative glass bg-white/70 rounded-[16px] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
        <h2 className="text-2xl font-bold text-slate-800 mb-6 flex items-center gap-2">
          <i className="fa-solid fa-cart-plus text-indigo-600"></i>
          Nova Compra
        </h2>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Nome da Compra</label>
            <input 
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className={`w-full px-4 py-3 rounded-xl border ${errors.name ? 'border-red-500 bg-red-50' : 'border-slate-200 focus:border-indigo-500'} outline-none transition-all`}
              placeholder="Ex: Notebook novo"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">Valor Total (R$)</label>
              <input 
                type="number"
                step="0.01"
                value={totalValue}
                onChange={(e) => setTotalValue(e.target.value)}
                className={`w-full px-4 py-3 rounded-xl border ${errors.totalValue ? 'border-red-500 bg-red-50' : 'border-slate-200 focus:border-indigo-500'} outline-none transition-all`}
                placeholder="0.00"
              />
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">Parcelas</label>
              <input 
                type="number"
                value={installments}
                onChange={(e) => setInstallments(e.target.value)}
                className={`w-full px-4 py-3 rounded-xl border ${errors.installments ? 'border-red-500 bg-red-50' : 'border-slate-200 focus:border-indigo-500'} outline-none transition-all`}
                placeholder="1"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Data da Compra</label>
            <input 
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:border-indigo-500 outline-none transition-all"
            />
          </div>

          <div className="flex gap-3 pt-4">
            <button 
              type="button"
              onClick={onClose}
              className="flex-1 bg-white border border-slate-200 text-slate-600 font-bold py-3 rounded-xl hover:bg-slate-50 transition-all"
            >
              Cancelar
            </button>
            <button 
              type="submit"
              className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"
            >
              Salvar
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default PurchaseModal;

import React, { useState } from 'react';
import { Purchase } from '../types';

interface AmortizationModalProps {
  purchase: Purchase;
  onClose: () => void;
  onSubmit: (amount: number, date: string) => void;
}

const AmortizationModal: React.FC<AmortizationModalProps> = ({ purchase, onClose, onSubmit }) => {
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || Number(amount) <= 0) {
      setError(true);
      return;
    }
    onSubmit(Number(amount), date);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-md" onClick={onClose}></div>
      <div className="relative glass bg-white/70 rounded-[16px] w-full max-w-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200">
        <h2 className="text-xl font-bold text-slate-800 mb-2 flex items-center gap-2">
          <i className="fa-solid fa-hand-holding-dollar text-green-600"></i>
          Amortização Extra
        </h2>
        <p className="text-sm text-slate-500 mb-6">Reduzindo saldo de: <span className="font-bold text-slate-700">{purchase.name}</span></p>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Valor da Amortização (R$)</label>
            <input 
              type="number"
              step="0.01"
              value={amount}
              autoFocus
              onChange={(e) => {
                  setAmount(e.target.value);
                  setError(false);
              }}
              className={`w-full px-4 py-3 rounded-xl border ${error ? 'border-red-500 bg-red-50' : 'border-slate-200 focus:border-green-500'} outline-none transition-all`}
              placeholder="0.00"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Data do Pagamento</label>
            <input 
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:border-green-500 outline-none transition-all"
            />
          </div>

          <div className="flex gap-3 pt-4">
            <button 
              type="button"
              onClick={onClose}
              className="flex-1 bg-white border border-slate-200 text-slate-600 font-bold py-3 rounded-xl hover:bg-slate-50 transition-all"
            >
              Cancelar
            </button>
            <button 
              type="submit"
              className="flex-1 bg-green-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-green-100 hover:bg-green-700 transition-all"
            >
              Amortizar
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AmortizationModal;

import React from 'react';

interface ConfirmationModalProps {
